<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{Lightning,Location,Search}from'@element-plus/icons-vue';import{getAllChargingStations,startCharging as startChargingApi}from'@/api/chargingStationsApi';import{useUserStore}from'@/stores/user';
const router=useRouter(),store=useUserStore(),loading=ref(false),stations=ref<any[]>([]),keyword=ref('');const norm=(s:any)=>String(s)==='0'||s==='available';const filtered=computed(()=>stations.value.filter(s=>norm(s.status)&&(!keyword.value||`${s.stationName}${s.location}`.includes(keyword.value))));const load=async()=>{loading.value=true;try{const r:any=await getAllChargingStations();stations.value=Array.isArray(r?.data)?r.data:[]}finally{loading.value=false}};onMounted(load);
const start=async(s:any)=>{const id=store.user?.id;if(!id){router.push('/user-login');return}try{const p=await ElMessageBox.prompt('请输入本次充电时长（分钟）','确认开始充电',{inputValue:'60',inputPattern:/^([1-9]|[1-9]\d|1[0-7]\d|180)$/,inputErrorMessage:'请输入 1—180 分钟'});const d=Number(p.value);await startChargingApi(id,s.stationId,d);ElMessage.success('充电已开始');router.push(`/charging/${s.stationId}?duration=${d}&location=${encodeURIComponent(s.location||'校园充电区')}`)}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
</script>
<template><div class="action-page"><header class="page-header"><p>START CHARGING</p><h1>立即充电</h1><span>选择空闲站点并设置本次充电时长</span></header><main class="stations-main"><div class="search-row"><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索空闲站点"/><span><i/> {{filtered.length}} 个站点可用</span></div><section v-loading="loading" class="cards"><article v-for="s in filtered" :key="s.stationId"><div class="icon"><Lightning/></div><div><h2>{{s.stationName}}</h2><p><Location/>{{s.location||'校园充电区'}}</p></div><dl><div><dt>功率</dt><dd>{{s.powerRating||7}} kW</dd></div><div><dt>价格</dt><dd>¥{{Number(s.pricePerHour||.5).toFixed(2)}}/小时</dd></div></dl><el-button type="primary" @click="start(s)">开始充电</el-button></article><el-empty v-if="!loading&&!filtered.length" description="暂无空闲充电桩"/></section></main></div></template>
<style scoped>.action-page{min-height:calc(100vh - 72px);padding-bottom:40px;background:var(--surface-muted)}.page-header p,.page-header h1,.page-header span{margin:0}.page-header p{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.11em}.page-header h1{margin:7px 0 9px}.page-header span{color:var(--text-secondary)}.search-row{display:flex;align-items:center;gap:18px;padding:15px;background:#fff;border:1px solid var(--border-color);border-radius:15px}.search-row .el-input{max-width:460px}.search-row>span{margin-left:auto;display:flex;align-items:center;gap:7px;color:var(--success);font-size:12px;font-weight:700}.search-row i{width:7px;height:7px;background:currentColor;border-radius:50%}.cards{min-height:240px;display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:18px}.cards article{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:15px;padding:22px;background:#fff;border:1px solid var(--border-color);border-radius:17px;box-shadow:var(--shadow-sm)}.icon{width:46px;height:46px;display:grid;place-items:center;color:var(--brand);background:var(--brand-soft);border-radius:13px}.icon :deep(svg){width:23px}.cards h2,.cards p{margin:0}.cards h2{font-size:16px}.cards p{display:flex;align-items:center;gap:4px;margin-top:6px;color:var(--text-muted);font-size:11px}.cards p :deep(svg){width:12px}.cards dl{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;margin:4px 0 0;padding:14px 0;border-block:1px solid #edf1ee}.cards dl div+div{padding-left:18px;border-left:1px solid #edf1ee}.cards dt{color:var(--text-muted);font-size:10px}.cards dd{margin:5px 0 0;font-size:13px;font-weight:700}.cards .el-button{grid-column:1/-1}@media(max-width:720px){.cards{grid-template-columns:1fr}.search-row{align-items:stretch;flex-direction:column}.search-row>span{margin-left:0}}</style>
